// HasRelay applies the HasEdge predicate on the "relay" edge.
func HasRelay() predicate.ConduitSession {
	return predicate.ConduitSession(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, RelayTable, RelayColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRelayWith applies the HasEdge predicate on the "relay" edge with a given conditions (other predicates).
func HasRelayWith(preds ...predicate.RelayInstance) predicate.ConduitSession {
	return predicate.ConduitSession(func(s *sql.Selector) {
		step := newRelayStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ConduitSession) predicate.ConduitSession {
	return predicate.ConduitSession(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ConduitSession) predicate.ConduitSession {
	return predicate.ConduitSession(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ConduitSession) predicate.ConduitSession {
	return predicate.ConduitSession(sql.NotPredicates(p))
}
